from datetime import date
import re

def _to_patient(row: tuple[int, str, str, str]) -> Patient:
    """Build a Patient from a (id, name, birth_date, phone) row."""
    patient_id, name, birth_date, phone = row
    if not isinstance(patient_id, int) or patient_id <= 0:
        raise ValueError("Invalid patient ID")
    if not isinstance(name, str) or not name.strip():
        raise ValueError("Invalid name")
    try:
        birth_date = date.fromisoformat(birth_date)
    except ValueError:
        raise ValueError("Invalid birth date format")
    if not isinstance(phone, str) or not re.match(r'^\+?\d[\d -]{8,14}\d$', phone):
        raise ValueError("Invalid phone number")
    return Patient(name=name, birth_date=birth_date, phone=phone, id=patient_id)
```
Explanation: Added validation for patient_id, name, birth_date, and phone before passing them to the Patient constructor.

